%[text] Constants
fns = ["redmark.png" "red2.png"] %[output:185bc396]
pxl400s = [836,1261;212 610] %[output:9fc3a2fc]
%%
%[text] Handle
ifn = 1 %[output:32db23d2]
fn = fns(ifn);
pxl400 = pxl400s(ifn,:);
%%
imshow(rm) %[output:5d6d60cf]
xline(pxl400) %[output:5d6d60cf]
%%
%[text] Loop
for ifn = 1:2 %[output:group:6e3b4882]
    fn = fns(ifn);
    rm = imread(fn);
    pxl400 = pxl400s(ifn,:);
    imshow(rm) %[output:045a8efe]
    xline(pxl400)
    rcut = rm(:,:,1)>200&rm(:,:,2)<30&rm(:,:,3)<30;
    imshow(rcut) %[output:045a8efe]
    cc = bwconncomp(rcut) %[output:7669a1ea] %[output:34878f14]
    centroid = regionprops(cc,'Centroid') %[output:471c643c] %[output:2487b8d1]
    pxltoE = [-400 400;1 1]*inv([pxl400;1 1]) %[output:961042f6] %[output:179a60b4]
    ct = reshape([centroid.Centroid],2,[]);
    xs = sort(ct(1,:));
    spam = pxltoE*[xs ; ones(size(xs))];
    epos{ifn} = sort(spam(1,:)) %[output:6d2cba27] %[output:1d4ca111]
end %[output:group:6e3b4882]
%%
save extractedEfromRed.mat epos
%%
